package dev.aragonite.powersync.client;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public class EndpointProfileTest {
 static final String BASE="https://library.example";
 static JSONObject profile(String key,String value)throws Exception {JSONObject h=new JSONObject();for(String k:new String[]{"onyxHostBaseUrl","onyxCloudDataHostBaseUrl","onyxLogHostBaseUrl","onyxContentHostBaseUrl","onyxSend2BooxHostBaseUrl","shopBookUrl"})h.put(k,BASE);h.put("onyxMaterialHostBaseUrl",BASE+"/boox/template-hub").put("onyxCouchbaseWSSHost","wss://library.example/boox-neocloud").put("onyxMessageReplicator","wss://library.example/boox-neocloud");if(key!=null)h.put(key,value);JSONObject o=new JSONObject();for(String k:new String[]{"ossNoteEndPoint","ossDeprecatedEndPoint","ossAIEndPoint","ossLogEndpoint","ossTestEndpoint"})o.put(k,BASE);for(String k:new String[]{"ossNoteBucket","ossDeprecatedBucket","ossAIBucket","ossLogBucket","ossTestBucket"})o.put(k,"ps-bucket");
  return new JSONObject().put("version",1).put("libraryId","11111111-1111-1111-1111-111111111111").put("deviceId","22222222-2222-2222-2222-222222222222").put("nativeUid","ps_synthetic").put("companionToken","c".repeat(32)).put("account",new JSONObject().put("account","synthetic").put("code","123456")).put("cluster",new JSONObject().put("clusterId","powersync_abcdef12").put("lang","powersync_abcdef12").put("name","Alexandria").put("region","self-hosted").put("clusterHost",h).put("ossConfig",o));}
 @Test public void acceptsServerAndExactStockHosts()throws Exception {EndpointProfile.validate(BASE,profile(null,null));for(java.util.Map.Entry<String,String> e:EndpointProfile.STOCK.entrySet())EndpointProfile.validate(BASE,profile(e.getKey(),e.getValue()));}
 @Test public void rejectsStockHostsOnTokenFieldsAndLookalikes()throws Exception {String[][] bad={{"onyxHostBaseUrl","https://push.boox.com"},{"onyxSend2BooxHostBaseUrl","https://push.boox.com"},{"onyxContentHostBaseUrl","https://push.boox.com"},{"onyxMaterialHostBaseUrl","https://en-client.boox.com"},{"onyxCloudDataHostBaseUrl","https://en-data.boox.com.evil.example"},{"onyxCloudDataHostBaseUrl","https://en-data.boox.com/"},{"onyxCloudDataHostBaseUrl","http://en-data.boox.com"},{"shopBookUrl","https://en-data.boox.com"}};for(String[] b:bad){try{EndpointProfile.validate(BASE,profile(b[0],b[1]));fail(b[0]+"="+b[1]);}catch(java.io.IOException expected){}}}
 @Test public void updatedEntryChangesOnlyEndpointValues()throws Exception {JSONObject p=profile(null,null);JSONObject entry=new JSONObject(p.getJSONObject("cluster").toString()).put("extra","kept");entry.getJSONObject("clusterHost").put("onyxCloudDataHostBaseUrl",BASE);JSONObject next=new JSONObject(p.getJSONObject("cluster").toString());next.getJSONObject("clusterHost").put("onyxCloudDataHostBaseUrl","https://en-data.boox.com");JSONArray changes=new JSONArray();JSONObject u=EndpointProfile.updatedEntry(entry,next,changes);assertEquals("[\"clusterHost.onyxCloudDataHostBaseUrl\"]",changes.toString());assertEquals("kept",u.getString("extra"));assertEquals("https://en-data.boox.com",u.getJSONObject("clusterHost").getString("onyxCloudDataHostBaseUrl"));assertEquals(BASE,entry.getJSONObject("clusterHost").getString("onyxCloudDataHostBaseUrl"));JSONArray none=new JSONArray();EndpointProfile.updatedEntry(u,next,none);assertEquals(0,none.length());}
 @Test public void replaceMarkerTouchesOnlyThisServer()throws Exception {JSONObject p=profile(null,null);JSONObject other=new JSONObject().put("serverId","someone_else").put("host",new JSONObject().put("onyxHostBaseUrl","https://other.example"));JSONArray m=new JSONArray().put(other).put(EndpointProfile.marker(p));p.getJSONObject("cluster").getJSONObject("clusterHost").put("shopBookUrl","https://push.boox.com");JSONArray out=new JSONArray(new String(EndpointProfile.replaceMarker(m.toString().getBytes("UTF-8"),p),"UTF-8"));assertEquals(2,out.length());assertEquals(other.toString(),out.getJSONObject(0).toString());assertEquals("https://push.boox.com",out.getJSONObject(1).getJSONObject("host").getString("shopBookUrl"));
  for(JSONArray bad:new JSONArray[]{new JSONArray().put(other),new JSONArray().put(EndpointProfile.marker(p)).put(EndpointProfile.marker(p))}){try{EndpointProfile.replaceMarker(bad.toString().getBytes("UTF-8"),p);fail(bad.toString());}catch(java.io.IOException expected){}}}
}
